<?php
$active_module='payments'; require_once __DIR__.'/layout.php';
$u=$supplier_user; $pdo=db(); $error=''; $notice=isset($_GET['saved'])?'Tahsilat ayarları kaydedildi. Sanal POS başvurusu inceleme aşamasına alındı.':'';
$q=$pdo->prepare('SELECT * FROM supplier_payment_settings WHERE supplier_id=?');$q->execute([$u['supplier_id']]);$settings=$q->fetch() ?: ['virtual_pos_enabled'=>0,'provider_name'=>'','merchant_name'=>'','settlement_iban'=>'','installment_enabled'=>0,'installment_max'=>'','pos_status'=>'draft'];
if($_SERVER['REQUEST_METHOD']==='POST'){
  $enabled=isset($_POST['virtual_pos_enabled'])?1:0;$provider=trim((string)($_POST['provider_name']??''));$merchant=trim((string)($_POST['merchant_name']??''));$iban=preg_replace('/\s+/','',strtoupper(trim((string)($_POST['settlement_iban']??''))));$installment=isset($_POST['installment_enabled'])?1:0;$max=$installment?max(2,min(18,(int)($_POST['installment_max']??2))):null;
  if($enabled && ($merchant==='' || !preg_match('/^TR\d{24}$/',$iban))) $error='Sanal POS başvurusu için üye işyeri ünvanı ve geçerli Türkiye IBAN’ı gereklidir.';
  else { $status=$enabled?'review':'draft';$stmt=$pdo->prepare('INSERT INTO supplier_payment_settings (supplier_id,virtual_pos_enabled,provider_name,merchant_name,settlement_iban,installment_enabled,installment_max,pos_status) VALUES (?,?,?,?,?,?,?,?) ON CONFLICT (supplier_id) DO UPDATE SET virtual_pos_enabled=EXCLUDED.virtual_pos_enabled,provider_name=EXCLUDED.provider_name,merchant_name=EXCLUDED.merchant_name,settlement_iban=EXCLUDED.settlement_iban,installment_enabled=EXCLUDED.installment_enabled,installment_max=EXCLUDED.installment_max,pos_status=EXCLUDED.pos_status,updated_at=now()');$stmt->execute([$u['supplier_id'],$enabled,$provider?:null,$merchant?:null,$iban?:null,$installment,$max,$status]);header('Location: /nexustraveltech/tedarikci/odeme-ayarlari?saved=1');exit; }
}
supply_start('Tahsilat & sanal POS', $active_module); ?>
